function hastToMarkDecorations(
  root: HastNode,
  basePos: number
): Range<Decoration>[] {
  const result: Range<Decoration>[] = [];
  let offset = 0;

  function walk(node: HastNode, cls?: string) {
    if (node.type === 'text') {
